namespace sv_b3bc2f2732844244899485ef80bb20b0.Services;

public class WarehouseState
{
    private string _selectedWarehouseId = "warehouse-a";

    public string SelectedWarehouseId => _selectedWarehouseId;

    public string SelectedWarehouseName => Warehouses
        .FirstOrDefault(w => w.Id == _selectedWarehouseId)?.Name ?? "Unknown";

    public event Action? OnChange;

    public static IReadOnlyList<WarehouseInfo> Warehouses { get; } =
    [
        new("warehouse-a", "Warehouse A — Main Distribution"),
        new("warehouse-b", "Warehouse B — East Regional"),
        new("warehouse-c", "Warehouse C — West Regional"),
        new("warehouse-d", "Warehouse D — Cold Storage"),
    ];

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public record WarehouseInfo(string Id, string Name);

namespace sv_b3bc2f2732844244899485ef80bb20b0.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling for the current circuit.
/// Each user circuit gets its own instance, so warehouse selections are independent.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired when new alert data arrives. Subscribers must wrap StateHasChanged
    /// in InvokeAsync since this fires from a background thread.
    /// </summary>
    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by components to start polling. Uses reference counting so polling
    /// runs as long as at least one subscriber is active.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
            // Fire an immediate first poll
            _ = RefreshAsync();
        }
    }

    /// <summary>
    /// Called by components when they no longer need polling (e.g., leaving the page).
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (_timer is not null && await _timer.WaitForNextTickAsync(ct))
            {
                await RefreshAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when polling is stopped
        }
    }

    private async Task RefreshAsync()
    {
        LowStockCount = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        OnAlertDataChanged?.Invoke();
    }

    private void OnWarehouseChanged()
    {
        // When the warehouse changes, immediately refresh if polling is active
        if (_subscriberCount > 0)
        {
            _ = RefreshAsync();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        _cts?.Cancel();
        _timer?.Dispose();
    }
}

