@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-nowrap" for="warehouseSelect">
        <strong>Site:</strong>
    </label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            value="@WarehouseState.SelectedWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.Warehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    private void HandleStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
    }
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.LowStockCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2" title="Low-stock items">
        @AlertService.LowStockCount
    </span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2" title="No low-stock items">
        0
    </span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertDataChanged += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
        {
            AlertService.OnAlertDataChanged -= _handler;
        }
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@inject WarehouseState WarehouseState
@implements IDisposable

<PageTitle>Dashboard — @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Viewing: <strong>@WarehouseState.SelectedWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.LowStockCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.LowStockCount
                </p>
                <p class="text-muted">items below minimum level</p>
                <small class="text-muted">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-header">Alert Activity Log</div>
            <div class="card-body">
                @if (_alertLog.Count == 0)
                {
                    <p class="text-muted">Waiting for first poll...</p>
                }
                else
                {
                    <ul class="list-group list-group-flush" style="max-height: 300px; overflow-y: auto;">
                        @foreach (var entry in _alertLog.AsEnumerable().Reverse().Take(20))
                        {
                            <li class="list-group-item d-flex justify-content-between">
                                <span>@entry.Count low-stock items detected</span>
                                <small class="text-muted">@entry.Timestamp.ToString("HH:mm:ss")</small>
                            </li>
                        }
                    </ul>
                }
            </div>
        </div>
    </div>
</div>

@code {
    private readonly List<AlertLogEntry> _alertLog = [];
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(() =>
        {
            _alertLog.Add(new(AlertService.LowStockCount, DateTime.Now));
            StateHasChanged();
        });
        _warehouseHandler = () => InvokeAsync(() =>
        {
            _alertLog.Clear();
            StateHasChanged();
        });

        AlertService.OnAlertDataChanged += _alertHandler;
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling when this page becomes visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        // Stop polling when the user leaves this page
        AlertService.StopPolling();

        if (_alertHandler is not null)
            AlertService.OnAlertDataChanged -= _alertHandler;
        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
    }

    private record AlertLogEntry(int Count, DateTime Timestamp);
}

