using sv_b3bc2f2732844244899485ef80bb20b0.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

// Scoped = per circuit (per user connection) on Blazor Server.
// Each manager gets independent warehouse selection and alert counts.
builder.Services.AddScoped<WarehouseState>();
builder.Services.AddScoped<InventoryAlertService>();

